#include "inverted_index.h"
#include <assert.h>
#include <stdio.h>
int main(void){InvertedIndex*x=inverted_index_create(4);assert(x);assert(inverted_index_add_document(x,3,"Data structures and algorithms"));assert(inverted_index_add_document(x,1,"Algorithms for DATA systems"));assert(inverted_index_add_document(x,2,"data data indexing"));assert(inverted_index_doc_freq(x,"DATA")==3);assert(inverted_index_doc_freq(x,"algorithms")==2);assert(inverted_index_doc_freq(x,"missing")==0);uint64_t d=0;assert(inverted_index_get_doc(x,"data",0,&d)&&d==1);assert(inverted_index_get_doc(x,"data",1,&d)&&d==2);assert(inverted_index_get_doc(x,"data",2,&d)&&d==3);uint64_t out[4]={0};size_t n=inverted_index_and(x,"data","algorithms",out,4);assert(n==2&&out[0]==1&&out[1]==3);for(uint64_t i=10;i<1010;++i){char text[64];snprintf(text,sizeof text,"term%llu shared",(unsigned long long)i);assert(inverted_index_add_document(x,i,text));}assert(inverted_index_doc_freq(x,"shared")==1000);assert(inverted_index_validate(x));inverted_index_free(x);puts("Inverted Index tests passed");return 0;}
